static int countPivots(int[] nums) {
    int n = nums.length;
    long[] rightMin = new long[n];
    long smallest = Long.MAX_VALUE;
    for (int i = n - 1; i >= 0; i--) {
        rightMin[i] = smallest;
        smallest = Math.min(smallest, nums[i]);
    }
    int count = 0;
    long leftMax = Long.MIN_VALUE;
    for (int i = 0; i < n; i++) {
        if (leftMax < nums[i] && nums[i] < rightMin[i]) count++;
        leftMax = Math.max(leftMax, nums[i]);
    }
    return count;
}

