int countPivots(const int* nums, int n) {
    long long* rightMin = malloc((n > 0 ? n : 1) * sizeof(long long));
    long long smallest = LLONG_MAX;
    for (int i = n - 1; i >= 0; i--) {
        rightMin[i] = smallest;
        if (nums[i] < smallest) smallest = nums[i];
    }
    int count = 0;
    long long leftMax = LLONG_MIN;
    for (int i = 0; i < n; i++) {
        if (leftMax < nums[i] && nums[i] < rightMin[i]) count++;
        if (nums[i] > leftMax) leftMax = nums[i];
    }
    free(rightMin);
    return count;
}

