static int longestAfterFlip(int[] bits) {
    int n = bits.length;
    int[] left = new int[n], right = new int[n];
    for (int i = 0; i < n; i++) {
        if (bits[i] == 1) left[i] = (i > 0 ? left[i - 1] : 0) + 1;
    }
    for (int i = n - 1; i >= 0; i--) {
        if (bits[i] == 1) right[i] = (i < n - 1 ? right[i + 1] : 0) + 1;
    }
    int best = 0;
    for (int x : left) best = Math.max(best, x);
    for (int i = 0; i < n; i++) {
        if (bits[i] == 0) {
            int l = i > 0 ? left[i - 1] : 0;
            int r = i < n - 1 ? right[i + 1] : 0;
            best = Math.max(best, l + 1 + r);
        }
    }
    return best;
}

