int longestAfterFlip(const int* bits, int n) {
    int* left = calloc(n + 1, sizeof(int));
    int* right = calloc(n + 1, sizeof(int));
    for (int i = 0; i < n; i++) {
        if (bits[i] == 1) left[i] = (i > 0 ? left[i - 1] : 0) + 1;
    }
    for (int i = n - 1; i >= 0; i--) {
        if (bits[i] == 1) right[i] = (i < n - 1 ? right[i + 1] : 0) + 1;
    }
    int best = 0;
    for (int i = 0; i < n; i++) if (left[i] > best) best = left[i];
    for (int i = 0; i < n; i++) {
        if (bits[i] == 0) {
            int l = i > 0 ? left[i - 1] : 0;
            int r = i < n - 1 ? right[i + 1] : 0;
            if (l + 1 + r > best) best = l + 1 + r;
        }
    }
    free(left); free(right);
    return best;
}

