int bestProfit(const int* prices, int n) {
    int lowest = prices[0], best = 0;
    for (int i = 1; i < n; i++) {
        if (prices[i] - lowest > best) best = prices[i] - lowest;
        if (prices[i] < lowest) lowest = prices[i];
    }
    return best;
}
